insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:porc', 'pork', array['en:pork']::text[], 'list', $r$[{"title":"Pork nems","intro":"Crispy fried rolls filled with pork, vermicelli and wood ear mushrooms.","minutes":60,"calories":350,"difficulty":"Difficile","imageSearch":"vietnamese spring rolls nem","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese recipe","serves":4,"items":[{"name":"rice paper sheet","plural":"rice paper sheets","qty":16,"unit":"","have":false},{"name":"minced pork","plural":"minced pork","qty":300,"unit":"g","have":false},{"name":"rice vermicelli","plural":"rice vermicelli","qty":50,"unit":"g","have":false},{"name":"dried wood ear mushroom","plural":"dried wood ear mushrooms","qty":10,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false},{"name":"frying oil","plural":"frying oil","qty":100,"unit":"cl","have":false},{"name":"green salad","plural":"green salad","qty":1,"unit":"","have":false}],"steps":[{"text":"Soak the vermicelli and mushrooms in hot water for 10 minutes, then chop them.","timer":null},{"text":"Mix the pork, vermicelli, mushrooms, grated carrot, egg and fish sauce.","timer":null},{"text":"Dampen a rice paper sheet, put a spoonful of filling on it, fold in the edges and roll up tightly.","timer":null},{"text":"Fry the nems in hot oil for 6 minutes, until golden.","timer":{"label":"Frying","min":6}},{"text":"Serve with lettuce leaves, mint and fish sauce.","timer":null}],"makes":{"n":16,"one":"spring roll","many":"spring rolls"}},{"title":"Cassoulet","intro":"Tender white beans, Toulouse sausage and duck confit, browned in the oven.","minutes":180,"calories":850,"difficulty":"Moyen","imageSearch":"cassoulet beans sausage duck","veg":false,"oven":true,"cold":false,"missing":"","origin":"South-