","plural":"white wine","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cook the crozets for 15 minutes in salted water.","timer":{"label":"Cooking","min":15}},{"text":"Brown the bacon and the sliced onions, then deglaze with the white wine.","timer":{"label":"Pan","min":8}},{"text":"Mix the crozets, the bacon, the onions and the cream in a dish.","timer":null},{"text":"Lay the halved reblochon on top, rind side up.","timer":null},{"text":"Bake for 20 minutes.","timer":{"label":"Oven","min":20}}]},{"title":"Quiche lorraine","intro":"The real quiche lorraine: crisp pastry, lardons and a creamy egg filling.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"quiche lorraine","veg":false,"oven":true,"cold":false,"missing":"","origin":"Lorraine speciality","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry into a tin and prick the base.","timer":null},{"text":"Fry the lardons in a pan for 5 min with no added fat, and spread them over the pastry.","timer":{"label":"Pan","min":5}},{"text":"Beat the eggs with the cream, milk, a little salt, pepper and the nutmeg.","timer":null},{"text":"Pour over the lardons and bake for 35 min, until golden.","timer":{"label":"Oven","min":35}}],"kids":true},{"title":"Tartiflette with reblochon","intro":"The great Savoyard classic: soft potatoes, bacon lardons and a reblochon that