insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:saucisse', 'sausage', array['en:sausage']::text[], 'list', $r$[{"title":"Cassoulet","intro":"Tender white beans, Toulouse sausage and duck confit, browned in the oven.","minutes":180,"calories":850,"difficulty":"Moyen","imageSearch":"cassoulet beans sausage duck","veg":false,"oven":true,"cold":false,"missing":"","origin":"South-West speciality","serves":4,"items":[{"name":"dried white bean","plural":"dried white beans","qty":500,"unit":"g","have":false},{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"duck confit leg","plural":"duck confit legs","qty":2,"unit":"","have":false},{"name":"smoked belly pork","plural":"smoked belly pork","qty":150,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"The day before, soak the beans in cold water.","timer":null},{"text":"Boil the beans for 1 h in water with the carrot, onion and bouquet garni.","timer":{"label":"Cooking","min":60}},{"text":"Brown the diced belly pork, the sausages and the duck in a pan.","timer":null},{"text":"Preheat the oven to 160 °C. In a dish, mix the drained beans, the tomatoes, the garlic and the meats, and add a little cooking water.","timer":null},{"text":"Sprinkle with breadcrumbs and bake for 1 h 30, breaking the crust twice.","timer":{"label":"Oven","min":90}}]},{"title":"Sausage and mash","intro":"Browned Toulouse sausages with homemade mash and onion gravy.","minutes":40,"calories":720,"difficulty":"Facile","imageSearch":"sausage mash onion gravy","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"beef stock cube","plural":"beef stock cubes","qty":1,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 min in salted water.","timer":{"label":"Cooking","min":20}},{"text":"Brown the sausages for 15 min in a pan, turning them.","timer":{"label":"Pan","min":15}},{"text":"Take them out and soften the sliced onions in the pan, then add the stock cube and 20 cl of water, and let it reduce.","timer":{"label":"Cooking","min":8}},{"text":"Mash the potatoes with the milk and the butter.","timer":null},{"text":"Serve the sausages on the mash, covered with gravy.","timer":null}],"kids":true},{"title":"Raclette","intro":"Raclette cheese melted over potatoes, with cured meats and gherkins.","minutes":40,"calories":850,"difficulty":"Facile","imageSearch":"raclette dinner","veg":false,"oven":false,"cold":false,"missing":"","origin":"Savoyard speciality","serves":4,"items":[{"name":"raclette cheese","plural":"raclette cheese","qty":800,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1200,"unit":"g","have":false},{"name":"cured ham","plural":"cured ham","qty":8,"unit":"slices","have":false},{"name":"rosette sausage","plural":"rosette sausage","qty":150,"unit":"g","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"gherkin","plural":"gherkins","qty":16,"unit":"","have":false},{"name":"pickled onion","plural":"pickled onions","qty":8,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in their skins for 25 minutes in salted water.","timer":{"label":"Cooking","min":25}},{"text":"Keep them warm in a tea towel.","timer":null},{"text":"Put the cured meats, the gherkins and the pickled onions on the table.","timer":null},{"text":"Everyone melts their own cheese in the raclette machine and pours it over their potatoes.","timer":null}],"kids":true},{"title":"Auvergne potée","intro":"Cabbage, vegetables and salted pork simmered together for a complete winter dish.","minutes":150,"calories":650,"difficulty":"Facile","imageSearch":"potee auvergnate cabbage pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Speciality of the Auvergne","serves":4,"items":[{"name":"green cabbage","plural":"green cabbages","qty":1,"unit":"","have":false},{"name":"lightly salted pork shoulder","plural":"lightly salted pork shoulders","qty":1,"unit":"","have":false},{"name":"morteau sausage","plural":"morteau sausages","qty":1,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false}],"steps":[{"text":"Soak the pork in cold water for 2 hours to remove the salt.","timer":null},{"text":"Put it in a large pot of cold water with the onion and the bouquet garni, and cook for 1 hour.","timer":{"label":"Cooking","min":60}},{"text":"Add the cabbage, cut into quarters and blanched for 5 minutes, the carrots and the turnips.","timer":null},{"text":"Cook for 30 minutes.","timer":{"label":"Cooking","min":30}},{"text":"Add the potatoes and the pricked sausage, and leave for 30 minutes.","timer":{"label":"Cooking","min":30}}]},{"title":"Sausage rougail","i