insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:oeuf', 'egg', array['en:egg']::text[], 'list', $r$[{"title":"Asparagus with mousseline sauce","intro":"Perfectly cooked white asparagus with a light mousseline sauce.","minutes":30,"calories":250,"difficulty":"Moyen","imageSearch":"white asparagus hollandaise","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white asparagus","plural":"white asparagus","qty":1000,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"single cream","plural":"single cream","qty":10,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false}],"steps":[{"text":"Peel the asparagus and boil it for 15 min in salted water.","timer":{"label":"Cooking","min":15}},{"text":"Whisk the egg yolks with 2 tbsp of water over a pan of simmering water until thick.","timer":null},{"text":"Add the melted butter little by little, then the lemon juice.","timer":null},{"text":"Whip the cream and fold it into the sauce.","timer":null},{"text":"Serve the warm asparagus with the sauce.","timer":null}]},{"title":"Butter shortbread","intro":"Little pure butter shortbread biscuits, cut out with a cutter.","minutes":50,"calories":90,"difficulty":"Facile","imageSearch":"butter shortbread cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":125,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the soft butter, sugar, vanil