:[{"text":"Cook the rice, then rinse it under cold water.","timer":{"label":"Cooking","min":12}},{"text":"Boil the eggs for 10 minutes and cut into quarters.","timer":{"label":"Cooking","min":10}},{"text":"Dice the tomatoes and pepper, and flake the tuna.","timer":null},{"text":"Toss everything with the sweetcorn, oil and vinegar, then season with salt and pepper.","timer":null}],"kids":true},{"title":"Tiramisu","intro":"Coffee-soaked biscuits, a mascarpone cream and a dusting of cocoa.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"tiramisu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dessert","serves":4,"items":[{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"sponge finger","plural":"sponge fingers","qty":20,"unit":"","have":false},{"name":"strong coffee","plural":"strong coffee","qty":30,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Whisk the yolks with the sugar, then add the mascarpone.","timer":null},{"text":"Whisk the whites until stiff and fold them in.","timer":null},{"text":"Quickly dip the sponge fingers in the cold coffee and line a dish with them.","timer":null},{"text":"Alternate cream and sponge fingers, finishing with cream.","timer":null},{"text":"Chill for 6 h, then dust with cocoa.","timer":{"label":"Chill","min":360}}],"dessert":true},{"title":"Crème caramel","intro":"The vanilla set custard, covered with its light caramel.","minutes":70,"calories":250,"difficulty":"Moyen","imageSearch":"creme caramel","veg":true,"oven":true,"cold":false,"missing":"","origin":"French dessert","serves":4,"items":[{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty"