","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Whisk the eggs and sugar until the mixture turns pale.","timer":null},{"text":"Add the lemon zest, flour, baking powder and a pinch of salt, then the melted butter.","timer":null},{"text":"Chill the batter for 1 h. This is the secret of the bump.","timer":{"label":"Rest","min":60}},{"text":"Preheat the oven to 220 °C. Fill the buttered moulds three-quarters full.","timer":null},{"text":"Bake for 5 min, turn the oven down to 180 °C and bake for another 5 min.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":24,"one":"madeleine","many":"madeleines"}},{"title":"Marble cake","intro":"The vanilla and chocolate loaf cake with pretty swirls, just like the one from tea time.","minutes":75,"calories":340,"difficulty":"Facile","imageSearch":"marble cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"melted butter","plural":"melted butter","qty":180,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"milk","plural":"milk","qty":5,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":25,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C and butter a loaf tin.","timer":null},{"text":"Whisk the melted butter, sugar and vanilla sugar, then add the eggs one by one.","timer":null},{"text":"Add the flour, baking powder and milk.","timer":null},{"text":"Split the batter in two and add the cocoa to one half.","timer":null},{"text":"Pour the batters into the tin in alternating layers and run a fork 